using System;using System.IO;using System.Linq;using Nexus;
class RemovalLinks {static int Main(string[] args){try{string root=args[0],folder=Path.Combine(root,"dedicated-port");var game=new Game{Name="Link fixture",Executable=Path.Combine(folder,"Game.exe")};bool rejected=false;try{PortRemoval.Build(game,new[]{game},Path.Combine(root,"data"),folder,false);}catch(IOException){rejected=true;}if(!rejected||!File.Exists(game.Executable)||File.ReadAllText(Path.Combine(root,"outside-copy","personal.dat"))!="preserve")throw new Exception("Junction fixture was not protected");Console.WriteLine("PASS junction rejected; external target and port untouched");return 0;}catch(Exception ex){Console.Error.WriteLine(ex);return 1;}}}
